-- GENERATED by `wfj generate` from data/gossip/gossip-c1.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["c1001c3f5ffa1cd4"] = { "Il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo distruggerà!", "." },
  ["c1038cf54ed7d476"] = { "Il corpo di %s cade a terra, un mucchio senza vita.", "." },
  ["c1063221546e3be3"] = { "Allora devi parlare con Osborne. A ⟦Stormwind=Roccavento⟧ non c'è maestro delle arti furtive migliore di lui. Cercalo nella Città Vecchia.", "." },
  ["c11cfefd5874bcb5"] = { "Sì, subito, mamma!", "." },
  ["c11eacf43d2e2c82"] = { "La mia fede guida le mie azioni, {race}. So che Ivus verrà.", "." },
  ["c13766548658c2f4"] = { "Noi, l'⟦Alliance=Alleanza⟧, trionferemo!", "." },
  ["c1386a7d03d5eb5a"] = { "Non sono qui a insegnare ai poppanti appena usciti dalla culla. Non hai neanche lontanamente l'abilità che pretendo dai miei allievi. Anzi, sei <un/una> <ragazzo/ragazza> che fa pena, e ti pregherei di non restare lì a blaterare.", "." },
  ["c14030101bc1bad2"] = { "La vostra prigione è nostra!", "." },
  ["c141e9c42898481e"] = { "Riempi il boccale e prendi una sedia. Abbiamo storie da raccontare e barili da svuotare.", "." },
  ["c14bba44cf65d039"] = { "Sapevo da tempo che mi avresti cercato, {name}.\n\nOgni essere senziente di questo mondo è guidato dalle scelte che compie. Le scelte generano altre scelte, e queste a loro volta fanno di ciascuno ciò che è. È da qui che si trae la tua fortuna: da chi sei e dalle scelte che compi.\n\nSei pronto a scoprire dove si trova la tua fortuna?", "." },
  ["c1502329b5e5da59"] = { "percepisce la tua paura.", "." },
  ["c16317f43e5e1282"] = { "Ehi! Ti piace la salsa? È buona la salsa, no?", "." },
  ["c1635d2bef75a099"] = { "Ti do il benvenuto nella Lega degli Esploratori. Se ti servono informazioni e si trovano in un libro, forse posso aiutarti.", "." },
  ["c1643adcca256322"] = { "Non mi farò attirare lontano da questo luogo.", "." },
  ["c16baa73f912dc39"] = { "⟦Glacial Gloves=Guanti Glaciali⟧.", "." },
  ["c173cf36fbb3a23e"] = { "Troppo facile.", "." },
  ["c173f35f68a64b50"] = { "Che te ne pare del mio famiglio?", "." },
  ["c1776de7d6b3e0e5"] = { "Non voglio tornare al lavoro", "." },
  ["c187160beea2aeae"] = { "Bene, {name}, mettiamoci al lavoro su quei calderoni! Se vuoi raccogliere i componenti che ci servono, prendi da me un Focalizzatore Vitreo. Dovrai averlo con te per individuare le risorse necessarie che si trovano addosso al Flagello e che trasformeranno quei calderoni.\n\nTi servirà anche una dose di Accelerante Arcano per i calderoni. Non costa poco, e non è stabile. Una volta che l'avrai, avrai solo trenta minuti per usarlo prima che scada: compralo con giudizio.", "." },
  ["c18e30bc5feadf57"] = { "Finalmente, la libertà... Ora devo andare, grazie per avermi aiutato a fuggire. Al ⟦Freewind Post=Presidio di Ventolibero⟧ ci torno senza bisogno d'aiuto.", "." },
  ["c191d43d73957b1c"] = { "Giustizia elettrica!", "." },
  ["c19d65e9d069f3ac"] = { "La gente di ⟦Darkshire=Borgoscuro⟧ si aspetta di più dal Consiglio. Non possiamo lasciarla soffrire per quest'ira empia che ci affligge.", "." },
  ["c1a04e53b6444d68"] = { "%s esamina il sangue nella bottiglia.", "." },
  ["c1ab234dee2fb2a1"] = { "È stato semplice, una volta spezzato il suo spirito.", "." },
  ["c1ac8418d3549e36"] = { "Gli Shen'dralar erano gli arcanisti più venerati della regina Azshara. Proprio fra queste mura venivano trattate le richieste più importanti della regina, spesso in segreto.\n\nDopo la distruzione del Pozzo e il torpore che ne seguì, calato sugli ⟦Highborne=Alti Nobili⟧ e sulle sette minori degli elfi della notte, il principe di Eldre'Thalas, Tortheldrin, iniziò a costruire i piloni che vedi sparsi nelle sale dell'ala ovest.", "." },
  ["c1b85019493cf743"] = { "I segreti di Suntara non lasceranno queste terre.", "." },
  ["c1ca3f7e91ef0dd1"] = { "Allora, la fai saltare quella porta?", "." },
  ["c1cd944a77286c1d"] = { "Io fare quel che posso per addestrarti nelle vie dei sacerdoti, se è per questo che tu essere qui.", "." },
  ["c1cdcfb0fc174670"] = { "È questo il meglio che sono riusciti a fare?\n\n<Omarion trova la forza di ridere.>\n\nNon hai la determinazione per affrontare un mostro come Kel'Thuzad. Crollerai davanti ai suoi servitori, proprio come quelli che sono venuti prima di te...\n\nLasciami qui a morire. Mi rifiuto di tornare in un mondo che esalta quelli come te.", "." },
  ["c1cdfcd0827d5808"] = { "Possibile? Qualcuno che attraversa queste sale con uno scopo? Sì, un fuoco giusto ti arde nel petto, {race}.\n\nLa mia vita potrebbe finire presto, ma il sapere che custodisco deve essere condiviso con il mondo. Del resto, è per questo che mi trovo qui.\n\nPadroneggi un mestiere?", "." },
  ["c1d44f1f9ca1f488"] = { "Da me non imparerai niente di nuovo: ne sai già troppo. Se vuoi altro addestramento, parla con la tauren ⟦Una=Uma⟧ nelle botteghe a nord-ovest dell'altopiano centrale di Picco del Tuono. Portale i miei saluti, eh?", "." },
  ["c1d4b2ed9909d256"] = { "Hai dei famigli da accudire? Basta che poi pulisci dove sporcano! Cerca Shoja'my davanti alla locanda.", "." },
  ["c1e59e6f61303b54"] = { "Mi spiace, {class}, ma devi diventare più potente prima che io possa lasciarti entrare nel ⟦Arathi Basin=Bacino d'Arathi⟧.", "." },
  ["c1ee62c2c3f183d0"] = { "Gli Dei Primordiali? Impossibile!", "." },
  ["c1f0bd1bf109bef1"] = { "Quando il rappresentante parla con te, comincia ogni battuta con il tuo nome. Se non vedi il tuo nome, non sta ancora parlando con te.", "." },
  ["c1f184c0eb8dcda8"] = { "Dovresti parlare con ⟦Gelman Stonehand=Gelman Mandipietra⟧. Mi pare che abbia una casa nel Distretto dei Nani, ma non ricordo bene. Io darei un'occhiata lì.", "." },
  ["c1fa2f35a4ae7816"] = { "Ansekhwa, il maestro d'armi tauren, si trova sull'altura inferiore di Picco del Tuono. Può insegnare le mazze a una e a due mani, i bastoni e i fucili.\n\nHanashi, qui accanto a me, può istruirti nell'uso degli archi, delle asce a una e a due mani, dei bastoni e di ogni genere di armi da lancio.\n\nArchibald, il maestro d'armi non morto nel ⟦War Quarter=Quartiere della Guerra⟧ di ⟦Undercity=Sepulcra⟧, può insegnare l'uso delle balestre, dei pugnali, delle spade a una e a due mani e delle armi in asta.", "." },
  ["c1ffd5933a17df9e"] = { "Tocca... a te.", "." },
})
